action.script:
set -eu
umask 077
clean_cache="$(/usr/bin/getconf DARWIN_USER_CACHE_DIR)notchany-keyboard-cleaning"
/bin/mkdir -p "$clean_cache"
/bin/chmod 700 "$clean_cache"
clean_source="$NOTCH_TEMP_DIR/NotchClean.swift"
cat > "$clean_source" <<'NOTCH_CLEAN_SWIFT_SOURCE'
import AppKit
import ApplicationServices
import CoreGraphics
import Darwin

let ipcName = "com.local.notchclean.control.\(getuid())"
let maximumDuration: TimeInterval = 600
let messages: [String: String] = {
    guard let raw = ProcessInfo.processInfo.environment["NOTCH_I18N"],
          let data = raw.data(using: .utf8),
          let value = try? JSONSerialization.jsonObject(with: data) as? [String: String] else { return [:] }
    return value
}()

func t(_ key: String, _ fallback: String) -> String { messages[key] ?? fallback }

func playEffect(_ preset: String, duration: Int) -> Process? {
    let cli = URL(fileURLWithPath: ProcessInfo.processInfo.environment["NOTCH_CLEAN_CLI"]
        ?? "/Applications/NotchAny.app/Contents/Helpers/notchany-cli")
    guard FileManager.default.isExecutableFile(atPath: cli.path) else { return nil }
    let process = Process()
    process.executableURL = cli
    let effect = String(decoding: jsonData(["preset": preset, "duration_ms": duration]), as: UTF8.self)
    process.arguments = ["test-effect", "--request", effect, "--visible"]
    process.standardInput = FileHandle.nullDevice
    process.standardOutput = FileHandle.nullDevice
    process.standardError = FileHandle.nullDevice
    do { try process.run(); return process } catch { return nil }
}

func jsonData(_ value: [String: Any]) -> Data {
    (try? JSONSerialization.data(withJSONObject: value, options: [.sortedKeys])) ?? Data("{}".utf8)
}

func emit(_ value: [String: Any]) {
    print(String(decoding: jsonData(value), as: UTF8.self))
}

func request(_ message: Int32) -> [String: Any]? {
    guard let port = CFMessagePortCreateRemote(nil, ipcName as CFString) else { return nil }
    var reply: Unmanaged<CFData>?
    let code = CFMessagePortSendRequest(port, message, nil, 0.3, 0.5,
                                       CFRunLoopMode.defaultMode.rawValue, &reply)
    guard code == kCFMessagePortSuccess, let data = reply?.takeRetainedValue() else { return nil }
    return (try? JSONSerialization.jsonObject(with: data as Data)) as? [String: Any]
}

func launch(_ argument: String) throws {
    let process = Process()
    process.executableURL = Bundle.main.executableURL
    process.arguments = [argument]
    process.standardInput = FileHandle.nullDevice
    process.standardOutput = FileHandle.nullDevice
    process.standardError = FileHandle.nullDevice
    try process.run()
}

enum InputDecision { case block, move, unlock }

struct InputFilter {
    var unlockRects: [CGRect] = []
    var pressedKeys = Set<Int64>()
    var pressedButtons = Set<Int64>()
    var clickStartedInside = false
    var armedAt: TimeInterval = 0

    mutating func handle(_ type: CGEventType, _ event: CGEvent, now: TimeInterval) -> InputDecision {
        switch type {
        case .keyDown:
            let key = event.getIntegerValueField(.keyboardEventKeycode)
            pressedKeys.insert(key)
            let emergency: CGEventFlags = [.maskCommand, .maskAlternate, .maskControl]
            if key == 53 && event.flags.intersection(emergency) == emergency { return .unlock }
        case .keyUp:
            pressedKeys.remove(event.getIntegerValueField(.keyboardEventKeycode))
        case .leftMouseDown, .rightMouseDown, .otherMouseDown:
            pressedButtons.insert(event.getIntegerValueField(.mouseEventButtonNumber))
            if type == .leftMouseDown {
                clickStartedInside = now >= armedAt && unlockRects.contains { $0.contains(event.location) }
            }
        case .leftMouseUp, .rightMouseUp, .otherMouseUp:
            pressedButtons.remove(event.getIntegerValueField(.mouseEventButtonNumber))
            if type == .leftMouseUp {
                let unlock = clickStartedInside && unlockRects.contains { $0.contains(event.location) }
                clickStartedInside = false
                if unlock { return .unlock }
            }
        case .mouseMoved, .leftMouseDragged, .rightMouseDragged, .otherMouseDragged:
            return .move
        default:
            break
        }
        return .block
    }
}

final class CleaningView: NSView {
    let statusLabel = NSTextField(labelWithString: "")
    let countdownLabel = NSTextField(labelWithString: "")
    let unlockButton = NSButton(title: t("finish_cleaning", "Finish Cleaning"), target: nil, action: nil)
    var onUnlock: (() -> Void)?

    override var isFlipped: Bool { true }

    override init(frame: NSRect) {
        super.init(frame: frame)
        wantsLayer = true
        layer?.backgroundColor = NSColor(calibratedWhite: 0.055, alpha: 0.98).cgColor

        let symbol = NSImageView()
        symbol.image = NSImage(systemSymbolName: "keyboard", accessibilityDescription: nil)
        symbol.contentTintColor = NSColor(calibratedRed: 0.40, green: 0.86, blue: 0.69, alpha: 1)
        symbol.symbolConfiguration = NSImage.SymbolConfiguration(pointSize: 42, weight: .regular)
        symbol.translatesAutoresizingMaskIntoConstraints = false
        addSubview(symbol)

        let title = NSTextField(labelWithString: t("cleaning_mode", "Cleaning Mode"))
        title.font = .systemFont(ofSize: 28, weight: .semibold)
        title.textColor = .white
        title.alignment = .center
        title.translatesAutoresizingMaskIntoConstraints = false
        addSubview(title)

        statusLabel.stringValue = t("input_locked", "Keyboard, mouse buttons and scrolling are locked")
        statusLabel.font = .systemFont(ofSize: 15)
        statusLabel.textColor = NSColor(white: 0.76, alpha: 1)
        statusLabel.alignment = .center
        statusLabel.translatesAutoresizingMaskIntoConstraints = false
        addSubview(statusLabel)

        unlockButton.bezelStyle = .rounded
        unlockButton.controlSize = .large
        unlockButton.font = .systemFont(ofSize: 16, weight: .semibold)
        unlockButton.image = NSImage(systemSymbolName: "lock.open", accessibilityDescription: nil)
        unlockButton.imagePosition = .imageLeading
        unlockButton.contentTintColor = .white
        unlockButton.bezelColor = NSColor(calibratedRed: 0.12, green: 0.48, blue: 0.35, alpha: 1)
        unlockButton.target = self
        unlockButton.action = #selector(unlock)
        unlockButton.toolTip = t("restore_input", "Restore keyboard and mouse input")
        unlockButton.translatesAutoresizingMaskIntoConstraints = false
        addSubview(unlockButton)

        countdownLabel.font = .monospacedDigitSystemFont(ofSize: 13, weight: .regular)
        countdownLabel.textColor = NSColor(white: 0.53, alpha: 1)
        countdownLabel.alignment = .center
        countdownLabel.translatesAutoresizingMaskIntoConstraints = false
        addSubview(countdownLabel)

        NSLayoutConstraint.activate([
            symbol.widthAnchor.constraint(equalToConstant: 64),
            symbol.heightAnchor.constraint(equalToConstant: 52),
            symbol.centerXAnchor.constraint(equalTo: centerXAnchor),
            symbol.bottomAnchor.constraint(equalTo: title.topAnchor, constant: -22),
            title.centerXAnchor.constraint(equalTo: centerXAnchor),
            title.centerYAnchor.constraint(equalTo: centerYAnchor, constant: -38),
            statusLabel.centerXAnchor.constraint(equalTo: centerXAnchor),
            statusLabel.topAnchor.constraint(equalTo: title.bottomAnchor, constant: 16),
            unlockButton.widthAnchor.constraint(equalToConstant: 220),
            unlockButton.heightAnchor.constraint(equalToConstant: 44),
            unlockButton.centerXAnchor.constraint(equalTo: centerXAnchor),
            unlockButton.topAnchor.constraint(equalTo: statusLabel.bottomAnchor, constant: 34),
            countdownLabel.centerXAnchor.constraint(equalTo: centerXAnchor),
            countdownLabel.topAnchor.constraint(equalTo: unlockButton.bottomAnchor, constant: 18)
        ])
        updateCountdown(600)
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }
    @objc func unlock() { onUnlock?() }

    func updateCountdown(_ seconds: Int) {
        countdownLabel.stringValue = String(format: t("auto_unlock_format", "%02d:%02d until automatic unlock"), seconds / 60, seconds % 60)
    }
}

final class ShieldWindow: NSWindow {
    override var canBecomeKey: Bool { true }
    override var canBecomeMain: Bool { false }
}

final class CleaningController: NSObject, NSApplicationDelegate {
    var tap: CFMachPort?
    var tapSource: CFRunLoopSource?
    var controlPort: CFMessagePort?
    var controlSource: CFRunLoopSource?
    var windows: [ShieldWindow] = []
    var filter = InputFilter()
    var startedAt = ProcessInfo.processInfo.systemUptime
    var deadline: TimeInterval = 0
    var state = "starting"
    var timer: Timer?
    var lockFD: Int32 = -1
    var signalSources: [DispatchSourceSignal] = []
    var effectProcesses: [Process] = []
    var didStop = false

    func applicationShouldHandleReopen(_ sender: NSApplication, hasVisibleWindows flag: Bool) -> Bool {
        beginUnlock()
        return false
    }

    func applicationDidFinishLaunching(_ notification: Notification) {
        let lockPath = FileManager.default.temporaryDirectory.appendingPathComponent("notchclean-\(getuid()).lock").path
        lockFD = Darwin.open(lockPath, O_CREAT | O_RDWR | O_NOFOLLOW, 0o600)
        guard lockFD >= 0, flock(lockFD, LOCK_EX | LOCK_NB) == 0 else {
            NSApp.terminate(nil)
            return
        }

        var context = CFMessagePortContext(version: 0,
            info: Unmanaged.passUnretained(self).toOpaque(), retain: nil, release: nil, copyDescription: nil)
        controlPort = CFMessagePortCreateLocal(nil, ipcName as CFString, { _, message, _, pointer in
            guard let pointer else { return nil }
            let controller = Unmanaged<CleaningController>.fromOpaque(pointer).takeUnretainedValue()
            if message == 1 {
                controller.beginUnlock()
            }
            return Unmanaged.passRetained(jsonData(controller.snapshot()) as CFData)
        }, &context, nil)
        guard let controlPort else { NSApp.terminate(nil); return }
        controlSource = CFMessagePortCreateRunLoopSource(nil, controlPort, 0)
        CFRunLoopAddSource(CFRunLoopGetMain(), controlSource, .commonModes)

        guard AXIsProcessTrusted() else { fail("permission_required"); return }
        tap = CGEvent.tapCreate(tap: .cgSessionEventTap, place: .headInsertEventTap,
            options: .defaultTap, eventsOfInterest: CGEventMask.max, callback: { _, type, event, pointer in
                guard let pointer else { return Unmanaged.passUnretained(event) }
                let controller = Unmanaged<CleaningController>.fromOpaque(pointer).takeUnretainedValue()
                return controller.handleEvent(type, event)
            }, userInfo: Unmanaged.passUnretained(self).toOpaque())
        guard let tap else { fail("event_tap_failed"); return }
        tapSource = CFMachPortCreateRunLoopSource(nil, tap, 0)
        CFRunLoopAddSource(CFRunLoopGetMain(), tapSource, .commonModes)
        startedAt = ProcessInfo.processInfo.systemUptime
        deadline = startedAt + maximumDuration
        filter.armedAt = startedAt + 1
        makeShields()
        CGEvent.tapEnable(tap: tap, enable: true)
        guard CGEvent.tapIsEnabled(tap: tap) else { fail("event_tap_failed"); return }
        state = "locked"
        NSApp.activate(ignoringOtherApps: true)
        if let effect = playEffect("warning-edge", duration: 1800) { effectProcesses.append(effect) }

        NotificationCenter.default.addObserver(self, selector: #selector(screensChanged),
            name: NSApplication.didChangeScreenParametersNotification, object: nil)
        NSWorkspace.shared.notificationCenter.addObserver(self, selector: #selector(stop),
            name: NSWorkspace.willSleepNotification, object: nil)
        NSWorkspace.shared.notificationCenter.addObserver(self, selector: #selector(stop),
            name: NSWorkspace.sessionDidResignActiveNotification, object: nil)

        timer = Timer.scheduledTimer(withTimeInterval: 0.2, repeats: true) { [weak self] _ in self?.tick() }
        for signalNumber in [SIGTERM, SIGINT, SIGHUP] {
            signal(signalNumber, SIG_IGN)
            let source = DispatchSource.makeSignalSource(signal: signalNumber, queue: .main)
            source.setEventHandler { [weak self] in self?.stop() }
            source.resume()
            signalSources.append(source)
        }
    }

    func snapshot() -> [String: Any] {
        ["state": state, "accessibility": AXIsProcessTrusted(),
         "seconds_remaining": max(0, Int(ceil(deadline - ProcessInfo.processInfo.systemUptime))),
         "pid": ProcessInfo.processInfo.processIdentifier]
    }

    func handleEvent(_ type: CGEventType, _ event: CGEvent) -> Unmanaged<CGEvent>? {
        if type == .tapDisabledByTimeout || type == .tapDisabledByUserInput {
            // A disabled filter must release the shield, never leave a false locked state.
            DispatchQueue.main.async { self.stop() }
            return Unmanaged.passUnretained(event)
        }
        let decision = filter.handle(type, event, now: ProcessInfo.processInfo.systemUptime)
        switch decision {
        case .move:
            // Keep pointer travel available without forwarding drags or modifier shortcuts.
            event.type = .mouseMoved
            event.flags = []
            return Unmanaged.passUnretained(event)
        case .unlock:
            DispatchQueue.main.async { self.beginUnlock() }
            return nil
        case .block:
            return nil
        }
    }

    func beginUnlock() {
        guard state == "locked" else { return }
        state = "unlocking"
        for window in windows {
            (window.contentView as? CleaningView)?.statusLabel.stringValue =
                t("release_inputs", "Release all keys and mouse buttons to continue")
        }
        tick()
    }

    func tick() {
        let now = ProcessInfo.processInfo.systemUptime
        if now >= deadline { finish(celebrate: true); return }
        guard let tap, CGEvent.tapIsEnabled(tap: tap), AXIsProcessTrusted() else { stop(); return }
        if state == "unlocking" {
            let anyKeyHeld = (0..<128).contains { CGEventSource.keyState(.hidSystemState, key: CGKeyCode($0)) }
            let anyButtonHeld = (0..<32).contains {
                CGEventSource.buttonState(.hidSystemState, button: CGMouseButton(rawValue: UInt32($0))!)
            }
            if !anyKeyHeld && !anyButtonHeld {
                // The unlock click was consumed; remove the filter after its mouse-up.
                finish(celebrate: true)
                return
            }
        }
        for window in windows {
            (window.contentView as? CleaningView)?.updateCountdown(max(0, Int(ceil(deadline - now))))
        }
    }

    @objc func screensChanged() { makeShields() }

    func makeShields() {
        let previousWindows = windows
        windows = []
        filter.unlockRects = []
        guard let primaryScreen = NSScreen.screens.first else { stop(); return }
        let primaryTop = primaryScreen.frame.maxY
        for screen in NSScreen.screens {
            let window = ShieldWindow(contentRect: screen.frame, styleMask: [.borderless], backing: .buffered, defer: false)
            window.level = NSWindow.Level(rawValue: Int(CGWindowLevelForKey(.screenSaverWindow)) + 1)
            window.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary, .stationary, .ignoresCycle]
            window.isReleasedWhenClosed = false
            window.isOpaque = true
            window.backgroundColor = NSColor(white: 0.055, alpha: 1)
            let view = CleaningView(frame: NSRect(origin: .zero, size: screen.frame.size))
            view.onUnlock = { [weak self] in self?.beginUnlock() }
            window.contentView = view
            window.setFrame(screen.frame, display: true)
            view.layoutSubtreeIfNeeded()
            let buttonInWindow = view.unlockButton.convert(view.unlockButton.bounds, to: nil)
            let cocoaRect = window.convertToScreen(buttonInWindow)
            filter.unlockRects.append(CGRect(x: cocoaRect.minX, y: primaryTop - cocoaRect.maxY,
                                             width: cocoaRect.width, height: cocoaRect.height))
            window.orderFrontRegardless()
            windows.append(window)
        }
        windows.first?.makeKey()
        previousWindows.forEach { $0.orderOut(nil) }
    }

    func fail(_ code: String) {
        state = code
        if let tap { CGEvent.tapEnable(tap: tap, enable: false) }
        windows.forEach { $0.orderOut(nil) }
        DispatchQueue.main.asyncAfter(deadline: .now() + 2) { self.stop() }
    }

    @objc func stop() {
        finish(celebrate: false)
    }

    func finish(celebrate: Bool) {
        guard !didStop else { return }
        didStop = true
        let completedCleaning = celebrate && (state == "locked" || state == "unlocking")
        state = "stopping"
        if let tap { CGEvent.tapEnable(tap: tap, enable: false); CFMachPortInvalidate(tap) }
        tap = nil
        if let tapSource { CFRunLoopRemoveSource(CFRunLoopGetMain(), tapSource, .commonModes) }
        tapSource = nil
        windows.forEach { $0.orderOut(nil) }
        windows = []
        timer?.invalidate()
        timer = nil
        if let controlPort { CFMessagePortInvalidate(controlPort) }
        controlPort = nil
        if lockFD >= 0 { Darwin.close(lockFD); lockFD = -1 }

        // Restore input and remove every shield before asking NotchAny to celebrate.
        if completedCleaning, let effect = playEffect("confetti", duration: 2200) {
            effectProcesses.append(effect)
            effect.terminationHandler = { _ in DispatchQueue.main.async { NSApp.terminate(nil) } }
            if !effect.isRunning { NSApp.terminate(nil); return }
            DispatchQueue.main.asyncAfter(deadline: .now() + 2) {
                if effect.isRunning { effect.terminate() }
                NSApp.terminate(nil)
            }
        } else {
            NSApp.terminate(nil)
        }
    }

    func applicationWillTerminate(_ notification: Notification) {
        if let tap { CGEvent.tapEnable(tap: tap, enable: false); CFMachPortInvalidate(tap) }
    }
}

func selfTest() {
    var count = 0
    func check(_ condition: Bool, _ label: String) {
        guard condition else { fputs("FAILED: \(label)\n", stderr); exit(1) }
        count += 1
    }
    func key(_ type: CGEventType, _ code: CGKeyCode) -> CGEvent {
        CGEvent(keyboardEventSource: nil, virtualKey: code, keyDown: type == .keyDown)!
    }
    func mouse(_ type: CGEventType, _ point: CGPoint) -> CGEvent {
        CGEvent(mouseEventSource: nil, mouseType: type, mouseCursorPosition: point, mouseButton: .left)!
    }
    var filter = InputFilter(unlockRects: [CGRect(x: 10, y: 10, width: 100, height: 44)], armedAt: 1)
    check(filter.handle(.keyDown, key(.keyDown, 0), now: 2) == .block, "typing blocked")
    check(filter.handle(.keyUp, key(.keyUp, 0), now: 2) == .block, "key-up blocked")
    check(filter.pressedKeys.isEmpty, "key state drains")
    check(filter.handle(.flagsChanged, key(.flagsChanged, 56), now: 2) == .block, "modifiers blocked")
    check(filter.handle(.scrollWheel, CGEvent(source: nil)!, now: 2) == .block, "scroll blocked")
    check(filter.handle(CGEventType(rawValue: 14)!, CGEvent(source: nil)!, now: 2) == .block, "media keys blocked")
    check(filter.handle(CGEventType(rawValue: 29)!, CGEvent(source: nil)!, now: 2) == .block, "gestures blocked")
    check(filter.handle(.mouseMoved, mouse(.mouseMoved, .zero), now: 2) == .move, "pointer remains available")
    check(filter.handle(.leftMouseDragged, mouse(.leftMouseDragged, .zero), now: 2) == .move, "drag becomes pointer travel")
    check(filter.handle(.leftMouseDown, mouse(.leftMouseDown, .zero), now: 2) == .block, "outside click blocked")
    check(filter.handle(.leftMouseUp, mouse(.leftMouseUp, .zero), now: 2) == .block, "outside release blocked")
    let inside = CGPoint(x: 30, y: 30)
    _ = filter.handle(.leftMouseDown, mouse(.leftMouseDown, inside), now: 0.1)
    check(filter.handle(.leftMouseUp, mouse(.leftMouseUp, inside), now: 0.2) == .block, "opening click cannot unlock")
    _ = filter.handle(.leftMouseDown, mouse(.leftMouseDown, .zero), now: 2)
    check(filter.handle(.leftMouseUp, mouse(.leftMouseUp, inside), now: 2) == .block, "drag onto unlock cannot activate it")
    _ = filter.handle(.leftMouseDown, mouse(.leftMouseDown, inside), now: 2)
    check(filter.handle(.leftMouseUp, mouse(.leftMouseUp, .zero), now: 2) == .block, "release outside cannot unlock")
    _ = filter.handle(.leftMouseDown, mouse(.leftMouseDown, inside), now: 2)
    check(filter.handle(.leftMouseUp, mouse(.leftMouseUp, inside), now: 2) == .unlock, "deliberate unlock works")
    check(filter.pressedButtons.isEmpty, "button state drains")
    let emergency = key(.keyDown, 53)
    emergency.flags = [.maskControl, .maskAlternate, .maskCommand]
    check(filter.handle(.keyDown, emergency, now: 2) == .unlock, "emergency shortcut works")
    emit(["ok": true, "checks": count, "input_was_locked": false])
}

func renderPreview(_ path: String) {
    let app = NSApplication.shared
    app.setActivationPolicy(.prohibited)
    let view = CleaningView(frame: NSRect(x: 0, y: 0, width: 1000, height: 650))
    let window = NSWindow(contentRect: view.frame, styleMask: [.borderless], backing: .buffered, defer: false)
    window.contentView = view
    view.layoutSubtreeIfNeeded()
    guard let rep = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { exit(1) }
    view.cacheDisplay(in: view.bounds, to: rep)
    guard let data = rep.representation(using: .png, properties: [:]) else { exit(1) }
    do { try data.write(to: URL(fileURLWithPath: path)) } catch { fputs("\(error)\n", stderr); exit(1) }
    emit(["ok": true, "preview": path, "input_was_locked": false])
}

let args = Array(CommandLine.arguments.dropFirst())
let command = args.first ?? (AXIsProcessTrusted() ? "--serve" : "--request-access")
switch command {
case "--self-test":
    selfTest()
case "--render-preview":
    guard args.count == 2 else { exit(1) }
    renderPreview(args[1])
case "--status":
    emit(request(2) ?? ["state": "inactive", "accessibility": AXIsProcessTrusted()])
case "--probe":
    let trusted = AXIsProcessTrusted()
    let probe = trusted ? CGEvent.tapCreate(tap: .cgSessionEventTap, place: .headInsertEventTap,
        options: .defaultTap, eventsOfInterest: CGEventMask.max,
        callback: { _, _, event, _ in Unmanaged.passUnretained(event) }, userInfo: nil) : nil
    if let probe { CGEvent.tapEnable(tap: probe, enable: false); CFMachPortInvalidate(probe) }
    emit(["accessibility": trusted, "event_tap_available": probe != nil, "input_was_locked": false])
case "--unlock":
    emit(request(1) ?? ["state": "inactive", "accessibility": AXIsProcessTrusted()])
case "--request-access":
    let app = NSApplication.shared
    app.setActivationPolicy(.accessory)
    let options = [kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String: true] as CFDictionary
    _ = AXIsProcessTrustedWithOptions(options)
    NSWorkspace.shared.open(URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility")!)
    RunLoop.current.run(until: Date().addingTimeInterval(1))
case "--serve":
    let app = NSApplication.shared
    app.setActivationPolicy(.accessory)
    let controller = CleaningController()
    app.delegate = controller
    withExtendedLifetime(controller) { app.run() }
case "--toggle":
    if let existing = request(2) {
        let response = request(1) ?? ["state": "inactive", "accessibility": AXIsProcessTrusted()]
        emit(response.merging(["previous_state": existing["state"] ?? "locked"]) { _, new in new })
    } else if !AXIsProcessTrusted() {
        do { try launch("--request-access"); emit(["state": "permission_required", "accessibility": false]) }
        catch { emit(["state": "error", "message": error.localizedDescription]); exit(1) }
    } else {
        do {
            try launch("--serve")
            var response: [String: Any]?
            let until = Date().addingTimeInterval(4)
            repeat {
                Thread.sleep(forTimeInterval: 0.05)
                response = request(2)
            } while (response == nil || response?["state"] as? String == "starting") && Date() < until
            emit(response ?? ["state": "error", "message": t("filter_start_failed", "Could not start the input filter")])
            if response?["state"] as? String != "locked" { exit(1) }
        } catch { emit(["state": "error", "message": error.localizedDescription]); exit(1) }
    }
default:
    emit(["state": "error", "message": t("unknown_command", "Unknown command")])
    exit(1)
}
NOTCH_CLEAN_SWIFT_SOURCE
clean_hash="$(/usr/bin/shasum -a 256 "$clean_source" | /usr/bin/awk '{print $1}')"
clean_helper="$clean_cache/NotchClean-$clean_hash-$(/usr/bin/uname -m)"
if [[ ! -x "$clean_helper" ]]; then
  if ! /usr/bin/xcode-select -p >/dev/null 2>&1; then
    print -u2 -- "$(notch_t compiler_required)"
    exit 1
  fi
  clean_build="$(/usr/bin/mktemp -d "$clean_cache/build.XXXXXX")"
  trap '/bin/rm -rf -- "$clean_build"' EXIT
  if ! /usr/bin/swiftc -O -module-cache-path "$clean_cache/Modules" -framework AppKit -framework ApplicationServices "$clean_source" -o "$clean_build/NotchClean"; then
    print -u2 -- "$(notch_t build_failed)"
    exit 1
  fi
  /usr/bin/codesign --force --sign - --identifier com.local.notchclean "$clean_build/NotchClean" >/dev/null 2>&1
  /bin/mv -f "$clean_build/NotchClean" "$clean_helper"
fi
NOTCH_CLEAN_CLI='/Applications/NotchAny.app/Contents/Helpers/notchany-cli'
if [[ ! -x "$NOTCH_CLEAN_CLI" ]]; then
  NOTCH_CLEAN_CLI="$(/bin/ps -axo comm= | /usr/bin/sed -n 's|/Contents/MacOS/NotchAny$|/Contents/Helpers/notchany-cli|p' | /usr/bin/head -n 1)"
fi
export NOTCH_CLEAN_CLI
case "${NOTCH_WIDGET_EVENT:-}" in
  probe)
    clean_result="$("$clean_helper" --probe)"
    notch_result --summary "$(notch_t probe_complete)" --widget-json "$clean_result"
    exit 0
    ;;
  self-test)
    clean_result="$("$clean_helper" --self-test)"
    notch_result --summary "$(notch_t self_test_complete)" --widget-json "$clean_result"
    exit 0
    ;;
  status|refresh|trigger)
    clean_result="$("$clean_helper" --status)"
    notch_result --summary "$(notch_t status_updated)" --widget-json "$clean_result"
    exit 0
    ;;
esac
if ! clean_result="$("$clean_helper" --toggle)"; then
  print -u2 -- "$(notch_t start_failed): $clean_result"
  exit 1
fi
clean_state="$(print -r -- "$clean_result" | /usr/bin/plutil -extract state raw -o - -)"
case "$clean_state" in
  locked)
    notch_result --summary "$(notch_t cleaning_started)" --details "$(notch_t cleaning_started_details)" --widget-json "$clean_result"
    ;;
  unlocking|inactive)
    notch_result --summary "$(notch_t cleaning_finished)" --details "$(notch_t cleaning_finished_details)" --widget-json "$clean_result"
    ;;
  permission_required)
    print -u2 -- "$(notch_t permission_required)"
    exit 1
    ;;
  *)
    print -u2 -- "$(notch_t not_started): $clean_result"
    exit 1
    ;;
esac
